[{"order":1,"type":"heading","text":"Props Down, Events Up: defineProps and defineEmits in Vue.js"},{"order":2,"type":"paragraph","text":"Component communication is a core concept in Vue.js. To maintain a predictable data flow, Vue enforces a strict one-way data binding principle. This is best summarized by the phrase: props down, events up."},{"order":3,"type":"subheading","text":"Understanding Props Down"},{"order":4,"type":"paragraph","text":"Parent components pass data down to child components using props. In the Composition API, we use the compiler macro 'defineProps' to declare what inputs a component accepts."},{"order":5,"type":"code","text":"<script setup>
defineProps({
  title: {
    type: String,
    required: true
  },
  likes: Number
});
</script>

<template>
  <div class="card">
    <h2>{{ title }}</h2>
    <p>Likes: {{ likes }}</p>
  </div>
</template>"},{"order":6,"type":"subheading","text":"Understanding Events Up"},{"order":7,"type":"paragraph","text":"Child components should never mutate props directly. Instead, when something happens that the parent needs to know about, the child emits an event using 'defineEmits'."},{"order":8,"type":"code","text":"<script setup>
const emit = defineEmits(['increment']);

const handleClick = () => {
  emit('increment', 1);
};
</script>

<template>
  <button @click="handleClick">Add Like</button>
</template>"},{"order":9,"type":"subheading","text":"Putting It Together"},{"order":10,"type":"paragraph","text":"Here is how the parent component consumes the child component, passing data down via props and listening to events going up."},{"order":11,"type":"code","text":"<script setup>
import { ref } from 'vue';
import ChildComponent from './ChildComponent.vue';

const postTitle = ref('Vue 3 Composition API');
const totalLikes = ref(10);

const handleIncrement = (amount) => {
  totalLikes.value += amount;
};
</script>

<template>
  <ChildComponent 
    :title="postTitle" 
    :likes="totalLikes" 
    @increment="handleIncrement" 
  />
</template>"},{"order":12,"type":"bullet_point","text":"Always declare props with explicit types and validation rules for better maintainability."},{"order":13,"type":"bullet_point","text":"Use 'defineEmits' to document the events a component can trigger, making your components easier to test and reuse."}]
